import math

def prime_factorization_count(n):
    """Counts the number of distinct prime factors of n."""
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return len(factors)

def count_primes_up_to(n):
    """Counts the number of primes less than or equal to n (pi(n))."""
    if n < 2:
        return 0
    count = 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            count += 1
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return count

def legendre(n, p):
    """Calculates the exponent of prime p in n! (E_p(n!))."""
    count = 0
    i = p
    while i <= n:
        count += n // i
        i *= p
    return count

def omega_K(n):
    """Calculates omega(K) where K = n! / (7 * 17^2)."""
    if n < 1:
        return 0

    # 1. Count primes p <= n, p != 7, p != 17
    pi_n = count_primes_up_to(n)

    # Initial count of primes dividing K from primes other than 7 and 17
    m = pi_n
    if n >= 7:
        m -= 1 # Exclude 7
    if n >= 17:
        m -= 1 # Exclude 17

    # 2. Check if 7 divides K
    E7 = legendre(n, 7)
    # 7 divides K if E7(n!) - 1 >= 1, i.e., E7(n!) >= 2
    if E7 >= 2:
        m += 1

    # 3. Check if 17 divides K
    E17 = legendre(n, 17)
    # 17 divides K if E17(n!) - 2 >= 1, i.e., E17(n!) >= 3
    if E17 >= 3:
        m += 1

    return m

